(()=>{'use strict';const api=window.SessionOverlay,F=window.SessionFormat;let last;
 const set=(id,value,title)=>{const el=document.getElementById(id);if(el.textContent!==String(value))el.textContent=value;if(title!==undefined)el.title=title;};
 function render(state){last=state;const data=state.data||{},m=data.metrics||{},active=F.live(state);document.body.classList.toggle('compact',state.display?.compact===true);document.body.classList.toggle('warning',!!(state.error||state.storage?.error||state.engine?.warning));set('status',F.status(state));set('character',data.context?.character||'Ожидание персонажа');set('location',data.context?.location||'Откройте Albion Online');for(const[id,metric]of [['fame','Fame'],['damage','localDamage'],['healing','localHeal'],['silver','Silver'],['taken','localTakenDamage'],['loot','LootValue'],['might','Might'],['favor','Favor']])set(id,active?F.compact(m[metric]||0):'—',F.num(m[metric]||0));set('fame-rate',active?(data.famePerHour===null?'…':F.compact(data.famePerHour)):'—',data.famePerHour===null?'Оценка появится после минуты сессии':F.num(data.famePerHour));set('dps',active?F.num(data.dps10):'—');set('hps',active?F.num(data.hps10):'—');set('time',F.duration(data.durationSeconds)+' · сессия');}
 for(const action of ['compact','opacity','close'])document.getElementById(action).onclick=()=>api.command(action).catch(error=>set('status',error.message));
 api.onState(render);api.command('state').then(render).catch(error=>set('status',error.message));
})();
